CREATE TABLE agent_pairings (id TEXT PRIMARY KEY NOT NULL,owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE RESTRICT,operation_id TEXT NOT NULL,request_hash TEXT NOT NULL,code_hash TEXT NOT NULL UNIQUE,code_enc TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL,used_by TEXT,pair_operation_id TEXT,pair_hash TEXT,result_enc TEXT,UNIQUE(owner_id,operation_id),FOREIGN KEY(used_by,owner_id) REFERENCES local_agents(id,owner_id) ON DELETE RESTRICT);
